// CPL Pathways tab — renderer.
//
// STATIC consumer asset (NOT regenerated by excel_to_dashboard.py), lazy-loaded
// by the inline boot in the tab shell on first activation of #tab-cpl-pathways.
//
// Purpose: audience-facing degree-pathway course maps that show, for a specific
// college program, which required courses an incoming student can clear through
// CPL — apprenticeship articulations already live in the MAP platform (✓, no
// classroom seat time) and CLEP exam options for GE requirements (◆, per the
// CCCCO systemwide exam-credit charts, ESLEI 24-35). Built for the California
// Apprenticeship Council presentation (2026-08-13): the first pathway is
// Cerritos College's Field Ironworker Supervisor baccalaureate (fall 2027),
// where journeyworker ironworkers arrive with 30+ units of CPL on day one.
// The pathway DEFINITIONS live in cpl_pathways_data.js (curated, static); the
// ✓ marks are DERIVED at render time from the live CER dataset
// (credential_reference_data.js, regenerated daily), so the picture tracks the
// MAP platform as colleges add articulations. Baked fallbacks cover a CER load
// failure, with an honest "live data unavailable" note.
//
// Self-contained behind the CONFIG block (the map_export.js / map_users.js
// pattern). Scoped CSS injected from JS so both HTMLs are covered without a
// Rule-4 mirror. All DOM is built via createElement/textContent — no innerHTML
// with data (XSS safety; CodeQL js/xss).
(function () {
  "use strict";

  var ROOT_ID = "cpl-pathways-root";

  // ── Scoped CSS (var(--token) only — no raw hex) ──────────────────────────
  var CSS_ID = "cpl-pathways-css";
  var CSS = [
    ".cplpw { color: var(--text-body); max-width: 1080px; margin: 0 auto; }",
    ".cplpw-progrow { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin: 14px 0 4px; }",
    ".cplpw-progbtn { background: var(--surface-opaque); border:1px solid var(--border-strong); border-radius:18px; padding:6px 14px; font-size:.82rem; font-weight:600; color: var(--text-body); cursor:pointer; }",
    ".cplpw-progbtn.on { background: var(--seal-blue, var(--navy-primary)); color: var(--surface-opaque); border-color: transparent; }",
    ".cplpw-hero { background: var(--surface-opaque); border:1px solid var(--border); border-radius:12px; padding:18px 20px 16px; margin: 10px 0 14px; }",
    ".cplpw-hero .college { font-size:.82rem; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color: var(--text-muted); }",
    ".cplpw-hero h2 { margin:2px 0 4px; color: var(--text-strong); font-size:1.5rem; line-height:1.2; }",
    ".cplpw-hero .meta { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin: 6px 0 2px; }",
    ".cplpw-chip { display:inline-block; border-radius:10px; font-size:.7rem; font-weight:600; padding:2px 8px; border:1px solid var(--border-strong); color: var(--text-body); background: var(--surface-subtle); }",
    ".cplpw-chip.start { background: var(--mustard-fill); color: var(--text-strong); border-color: transparent; }",
    ".cplpw-hero .blurb { margin: 8px 0 0; color: var(--text-body); font-size:.9rem; max-width: 860px; }",
    ".cplpw-hero .facts { display:flex; flex-wrap:wrap; gap:6px 14px; margin-top:10px; }",
    ".cplpw-fact { font-size:.76rem; color: var(--text-muted); }",
    ".cplpw-fact::before { content:\"▪ \"; color: var(--mustard-text, var(--yellow-warning)); }",
    /* Stat tiles */
    ".cplpw-tiles { display:grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap:10px; margin: 12px 0; }",
    ".cplpw-tile { background: var(--surface-opaque); border:1px solid var(--border); border-radius:10px; padding:12px 14px; }",
    ".cplpw-tile .n { font-size:1.65rem; font-weight:800; line-height:1.1; color: var(--text-strong); }",
    ".cplpw-tile .n .u { font-size:.9rem; font-weight:600; color: var(--text-muted); margin-left:3px; }",
    ".cplpw-tile .l { font-size:.76rem; color: var(--text-muted); margin-top:3px; line-height:1.3; }",
    ".cplpw-tile.cpl .n { color: var(--hunter, var(--green-progress)); }",
    ".cplpw-tile.clep .n { color: var(--cobalt, var(--accent-link)); }",
    /* Unit meter */
    ".cplpw-meter { margin: 6px 0 4px; }",
    ".cplpw-meter .bar { display:flex; gap:2px; height:26px; border-radius:6px; overflow:hidden; background: var(--surface-muted); }",
    ".cplpw-meter .seg { min-width:0; display:flex; align-items:center; justify-content:center; font-size:.72rem; font-weight:700; color: var(--surface-opaque); white-space:nowrap; overflow:hidden; }",
    ".cplpw-meter .seg.cpl { background: var(--hunter, var(--green-progress)); }",
    ".cplpw-meter .seg.clep { background: var(--cobalt, var(--accent-link)); }",
    ".cplpw-meter .seg.rest { background: var(--surface-muted); color: var(--text-muted); }",
    ".cplpw-legend { display:flex; flex-wrap:wrap; gap:14px; margin: 8px 0 2px; font-size:.78rem; color: var(--text-muted); }",
    ".cplpw-legend .k { display:inline-flex; align-items:center; gap:5px; }",
    ".cplpw-glyph { font-weight:800; }",
    ".cplpw-glyph.cpl { color: var(--hunter, var(--green-progress)); }",
    ".cplpw-glyph.clep { color: var(--cobalt, var(--accent-link)); }",
    ".cplpw-glyph.rest { color: var(--text-faint); }",
    /* Section cards */
    ".cplpw-sections { display:grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap:12px; margin: 12px 0; align-items:start; }",
    ".cplpw-sec { background: var(--surface-opaque); border:1px solid var(--border); border-radius:10px; overflow:hidden; }",
    ".cplpw-sec.wide { grid-column: 1 / -1; }",
    ".cplpw-sec-head { padding:10px 14px 8px; border-bottom:1px solid var(--border); background: var(--surface-subtle); }",
    ".cplpw-sec-head .t { font-weight:700; color: var(--text-strong); font-size:.92rem; }",
    ".cplpw-sec-head .s { font-size:.75rem; color: var(--text-muted); margin-top:2px; }",
    ".cplpw-sec-head .sum { float:right; font-size:.75rem; font-weight:700; }",
    ".cplpw-sec-head .sum.cpl { color: var(--hunter, var(--green-progress)); }",
    ".cplpw-course { display:flex; align-items:baseline; gap:8px; padding:6px 14px; border-bottom:1px solid var(--border); font-size:.84rem; }",
    ".cplpw-course:last-child { border-bottom:none; }",
    ".cplpw-course.done { background: color-mix(in srgb, var(--hunter, var(--green-progress)) 7%, var(--surface-opaque)); }",
    ".cplpw-course .g { flex:0 0 18px; text-align:center; }",
    ".cplpw-course .code { flex:0 0 92px; font-weight:600; color: var(--text-strong); font-size:.78rem; }",
    ".cplpw-course .t { flex:1 1 auto; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }",
    ".cplpw-course.done .t { }",
    ".cplpw-course .u { flex:0 0 auto; font-size:.76rem; color: var(--text-muted); }",
    ".cplpw-course .how { flex:0 0 auto; font-size:.68rem; font-weight:600; border-radius:8px; padding:1px 7px; }",
    ".cplpw-course .how.cpl { color: var(--hunter, var(--green-progress)); border:1px solid var(--hunter, var(--green-progress)); }",
    ".cplpw-course .how.clep { color: var(--cobalt, var(--accent-link)); border:1px solid var(--cobalt, var(--accent-link)); cursor:pointer; background:none; font-family:inherit; }",
    ".cplpw-clepopts { padding:4px 14px 8px 40px; font-size:.76rem; color: var(--text-body); border-bottom:1px solid var(--border); }",
    ".cplpw-clepopts ul { margin:4px 0 2px; padding-left:16px; }",
    ".cplpw-clepopts li { margin:1px 0; }",
    /* Campaign callout */
    ".cplpw-callout { background: var(--navy-primary); color: var(--paper, var(--surface-opaque)); border-radius:12px; padding:18px 22px; margin: 14px 0; }",
    ".cplpw-callout .k { font-size:.72rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color: var(--mustard-on-dark, var(--gold-accent)); }",
    ".cplpw-callout .h { font-size:1.28rem; font-weight:800; margin:4px 0 4px; line-height:1.3; color: var(--surface-opaque); }",
    ".cplpw-callout .s { font-size:.85rem; opacity:.85; }",
    /* Footnotes */
    ".cplpw-foot { font-size:.74rem; color: var(--text-muted); margin: 12px 0 20px; line-height:1.55; }",
    ".cplpw-foot a { color: var(--accent-link); }",
    ".cplpw-note { font-size:.78rem; color: var(--mustard-text, var(--yellow-warning)); margin: 6px 0; }",
    "@media (max-width: 720px) { .cplpw-course .code { flex-basis:74px; } .cplpw-hero h2 { font-size:1.2rem; } }",
    "@media print { .cplpw-progrow { display:none; } .cplpw-sec { break-inside: avoid; } }",
  ].join("\n");

  function ensureCss() {
    if (document.getElementById(CSS_ID)) return;
    var s = document.createElement("style");
    s.id = CSS_ID;
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  // ── DOM helper — createElement/textContent only (no innerHTML with data) ──
  function el(tag, cls, kids) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (kids != null) {
      if (!Array.isArray(kids)) kids = [kids];
      kids.forEach(function (c) {
        if (c == null) return;
        if (typeof c === "string") n.appendChild(document.createTextNode(c));
        else n.appendChild(c);
      });
    }
    return n;
  }
  function clearNode(n) { while (n.firstChild) n.removeChild(n.firstChild); }
  function fmtU(u) {
    if (u == null || isNaN(u)) return "—";
    var s = (Math.round(u * 10) / 10).toString();
    return s;
  }

  // ── Live CER cross-check ──────────────────────────────────────────────────
  // Normalize a course number so catalog spellings match MAP entry drift
  // ("40.5" vs "40.50"). Non-numeric course numbers pass through uppercased.
  function normNum(num) {
    var f = parseFloat(num);
    if (!isNaN(f) && /^[\d.]+$/.test(String(num).trim())) return f.toFixed(2);
    return String(num == null ? "" : num).trim().toUpperCase();
  }
  function courseKey(subj, num) {
    return String(subj == null ? "" : subj).trim().toUpperCase() + " " + normNum(num);
  }
  // Split a "SUBJ NUM" course code from the pathway definition.
  function splitCode(code) {
    var s = String(code == null ? "" : code).trim();
    var i = s.lastIndexOf(" ");
    if (i < 0) return null;
    return { subj: s.slice(0, i), num: s.slice(i + 1) };
  }

  // Build the live lookup indexes from the CER payload:
  //  artIdx:  "SUBJ N.NN" (per college) -> {credential, units, cpl_types}
  //  clepByArea: GE-area name -> [{exam, units, ut}] (system exam-credit chart)
  function buildLiveIndexes(payload, collegeName) {
    var artIdx = {};
    var clepByArea = {};
    if (!payload || !Array.isArray(payload.unified_titles)) return null;
    payload.unified_titles.forEach(function (u) {
      var ut = u && u.ut != null ? String(u.ut) : "";
      (u.articulations || []).forEach(function (a) {
        (a && a.local || []).forEach(function (loc) {
          if (!loc) return;
          var colleges = loc.colleges || [];
          var hit = colleges.some(function (c) {
            return String(c).toUpperCase().indexOf(String(collegeName).toUpperCase()) !== -1;
          });
          if (!hit) return;
          var key = courseKey(loc.subj, loc.num);
          if (!artIdx[key]) {
            artIdx[key] = {
              credential: ut,
              units: (typeof loc.u === "number") ? loc.u : null,
              cpl_types: u.cpl_types || [],
              local_title: loc.t != null ? String(loc.t) : "",
            };
          }
        });
      });
      // CLEP GE options come from the systemwide exam-credit chart baked into
      // the CER rows (kb/reference/ccc_ge_exam_credit.json, ESLEI 24-35).
      var ge = u.ge_credit;
      if (ge && ge.program === "CLEP" && !ge.na && Array.isArray(ge.areas)) {
        ge.areas.forEach(function (area) {
          if (!clepByArea[area]) clepByArea[area] = [];
          // De-dupe on exam name (CER carries a few spelling-variant rows).
          var exists = clepByArea[area].some(function (e) { return e.exam === ge.exam; });
          if (!exists) clepByArea[area].push({ exam: ge.exam, units: ge.units, ut: ut });
        });
      }
    });
    Object.keys(clepByArea).forEach(function (k) {
      clepByArea[k].sort(function (a, b) { return a.exam < b.exam ? -1 : 1; });
    });
    return { artIdx: artIdx, clepByArea: clepByArea, generatedAt: payload._generated_at || null };
  }

  // ── Pathway resolution ────────────────────────────────────────────────────
  // Walk the pathway definition and resolve each course/slot against the live
  // indexes (or the baked fallback when live is null). Returns the resolved
  // model the renderer consumes, including the unit buckets.
  function resolvePathway(prog, live) {
    var cplUnits = 0, clepUnits = 0, totalListed = 0;
    var sections = (prog.sections || []).map(function (sec) {
      var rows = (sec.courses || []).map(function (c) {
        var row = {
          code: c.code || null,
          title: c.title || "",
          units: (typeof c.units === "number") ? c.units : null,
          status: "rest",       // rest | cpl | clep
          how: null,            // chip text
          detail: null,         // hover title
          clepOptions: null,    // [{exam, units}]
        };
        // 1) Apprenticeship CPL — live match against the college's MAP
        //    articulations, falling back to the baked `cpl` stamp.
        var m = null;
        if (row.code && live) {
          var p = splitCode(row.code);
          if (p) m = live.artIdx[courseKey(p.subj, p.num)] || null;
        }
        if (!m && c.cpl && c.cpl.credential) {
          m = { credential: c.cpl.credential, units: row.units, cpl_types: c.cpl.types || [], local_title: row.title };
        }
        if (m) {
          row.status = "cpl";
          var viaTypes = (m.cpl_types && m.cpl_types.length) ? m.cpl_types.join(", ") : "CPL";
          row.how = "✓ CPL";
          row.detail = "Articulated in the MAP platform: “" + m.credential + "” → " + (row.code || row.title) + " (" + viaTypes + ")";
          if (typeof m.units === "number" && row.units == null) row.units = m.units;
        }
        // 2) CLEP option — GE slots declare a `clep_area`; qualifying exams
        //    come from the live chart (fallback: baked count).
        if (row.status !== "cpl" && c.clep_area) {
          var opts = (live && live.clepByArea[c.clep_area]) || c.clep_fallback || [];
          if (opts.length) {
            row.status = "clep";
            row.clepOptions = opts;
            row.how = "◆ CLEP × " + opts.length;
            row.detail = opts.length + " CLEP exam(s) carry systemwide GE credit in “" + c.clep_area + "” (ESLEI 24-35)";
          }
        }
        // `no_count` sections (e.g. alternate-track course lists) render and
        // live-resolve, but never enter the unit buckets — a student takes ONE
        // track, so counting both would overstate the CPL number.
        if (typeof row.units === "number" && !sec.no_count) {
          totalListed += row.units;
          if (row.status === "cpl") cplUnits += row.units;
          else if (row.status === "clep") clepUnits += row.units;
        }
        return row;
      });
      var secCpl = rows.reduce(function (s, r) { return s + (r.status === "cpl" && r.units ? r.units : 0); }, 0);
      var secAll = rows.reduce(function (s, r) { return s + (r.units || 0); }, 0);
      return { def: sec, rows: rows, cplUnits: secCpl, allUnits: secAll };
    });
    var total = (typeof prog.total_units === "number") ? prog.total_units : totalListed;
    return {
      sections: sections,
      cplUnits: Math.round(cplUnits * 10) / 10,
      clepUnits: Math.round(clepUnits * 10) / 10,
      totalUnits: total,
      restUnits: Math.max(0, Math.round((total - cplUnits - clepUnits) * 10) / 10),
    };
  }

  // ── Renderers ─────────────────────────────────────────────────────────────
  function renderMeter(model) {
    var wrap = el("div", "cplpw-meter");
    var bar = el("div", "bar");
    var total = model.totalUnits || 1;
    [["cpl", model.cplUnits, "✓ " + fmtU(model.cplUnits) + "u CPL"],
     ["clep", model.clepUnits, "◆ " + fmtU(model.clepUnits) + "u CLEP-eligible"],
     ["rest", model.restUnits, fmtU(model.restUnits) + "u in class"]].forEach(function (t) {
      if (!t[1]) return;
      var seg = el("div", "seg " + t[0], t[2]);
      seg.style.flexGrow = String(t[1]);
      seg.style.flexBasis = "0";
      seg.title = t[2] + " of " + fmtU(total) + " total units";
      bar.appendChild(seg);
    });
    wrap.appendChild(bar);
    var legend = el("div", "cplpw-legend", [
      el("span", "k", [el("span", "cplpw-glyph cpl", "✓"), " CPL from journeyworker training — already articulated in the MAP platform"]),
      el("span", "k", [el("span", "cplpw-glyph clep", "◆"), " GE requirement a CLEP exam can satisfy (systemwide chart; college applies it)"]),
      el("span", "k", [el("span", "cplpw-glyph rest", "○"), " remaining classroom coursework"]),
    ]);
    wrap.appendChild(legend);
    return wrap;
  }

  function renderTiles(model, prog) {
    var tiles = el("div", "cplpw-tiles");
    function tile(cls, num, unit, label) {
      var t = el("div", "cplpw-tile" + (cls ? " " + cls : ""));
      var n = el("div", "n", num);
      if (unit) n.appendChild(el("span", "u", unit));
      t.appendChild(n);
      t.appendChild(el("div", "l", label));
      return t;
    }
    tiles.appendChild(tile("cpl", "✓ " + fmtU(model.cplUnits), "units", "CPL on day one — journeyworker apprenticeship credit already articulated in MAP"));
    tiles.appendChild(tile("clep", "◆ " + fmtU(model.clepUnits), "units", "more GE units available by CLEP exam — no classroom seat time"));
    tiles.appendChild(tile(null, fmtU(model.totalUnits), "units", "total for the " + (prog.degree || "degree")));
    var pct = model.totalUnits ? Math.round(((model.cplUnits + model.clepUnits) / model.totalUnits) * 100) : 0;
    tiles.appendChild(tile(null, pct + "%", null, "of the degree reachable without repeating training you already have"));
    return tiles;
  }

  function renderSection(secModel) {
    var sec = el("div", "cplpw-sec" + (secModel.def.wide ? " wide" : ""));
    var head = el("div", "cplpw-sec-head");
    if (secModel.cplUnits > 0) {
      head.appendChild(el("span", "sum cpl", "✓ " + fmtU(secModel.cplUnits) + " / " + fmtU(secModel.allUnits) + "u by CPL"));
    } else if (secModel.allUnits > 0) {
      head.appendChild(el("span", "sum", fmtU(secModel.allUnits) + "u"));
    }
    head.appendChild(el("div", "t", secModel.def.title || ""));
    if (secModel.def.note) head.appendChild(el("div", "s", secModel.def.note));
    sec.appendChild(head);
    secModel.rows.forEach(function (r) {
      var row = el("div", "cplpw-course" + (r.status === "cpl" ? " done" : ""));
      var glyph = r.status === "cpl" ? "✓" : (r.status === "clep" ? "◆" : "○");
      row.appendChild(el("span", "g cplpw-glyph " + (r.status === "cpl" ? "cpl" : r.status === "clep" ? "clep" : "rest"), glyph));
      if (r.code) row.appendChild(el("span", "code", r.code));
      var t = el("span", "t", r.title);
      t.title = r.detail || r.title;
      row.appendChild(t);
      if (r.units != null) row.appendChild(el("span", "u", fmtU(r.units) + "u"));
      if (r.status === "cpl") {
        var chip = el("span", "how cpl", r.how);
        chip.title = r.detail || "";
        row.appendChild(chip);
      }
      var optsPanel = null;
      if (r.status === "clep" && r.clepOptions) {
        var btn = document.createElement("button");
        btn.className = "how clep";
        btn.type = "button";
        btn.textContent = r.how;
        btn.title = (r.detail || "") + " — click to list the exams";
        btn.setAttribute("aria-expanded", "false");
        btn.addEventListener("click", function () {
          var open = optsPanel.style.display !== "none";
          optsPanel.style.display = open ? "none" : "";
          btn.setAttribute("aria-expanded", open ? "false" : "true");
        });
        row.appendChild(btn);
        optsPanel = el("div", "cplpw-clepopts");
        optsPanel.style.display = "none";
        optsPanel.appendChild(el("div", null, "CLEP exams carrying systemwide GE credit here (min " +
          "3 semester units each; passing score 50 — ESLEI 24-35):"));
        var ul = el("ul");
        r.clepOptions.forEach(function (o) {
          ul.appendChild(el("li", null, o.exam + (o.units ? " — " + fmtU(o.units) + "u" : "")));
        });
        optsPanel.appendChild(ul);
      }
      sec.appendChild(row);
      if (optsPanel) sec.appendChild(optsPanel);
    });
    return sec;
  }

  function renderProgram(root, prog, live, liveNote) {
    var model = resolvePathway(prog, live);
    var frag = document.createDocumentFragment();

    // Hero
    var hero = el("div", "cplpw-hero");
    hero.appendChild(el("div", "college", prog.college || ""));
    hero.appendChild(el("h2", null, (prog.program || "") + (prog.degree ? " — " + prog.degree : "")));
    var meta = el("div", "meta");
    if (prog.start) meta.appendChild(el("span", "cplpw-chip start", "First cohort: " + prog.start));
    if (prog.status) meta.appendChild(el("span", "cplpw-chip", prog.status));
    if (prog.audience) meta.appendChild(el("span", "cplpw-chip", prog.audience));
    hero.appendChild(meta);
    if (prog.blurb) hero.appendChild(el("p", "blurb", prog.blurb));
    if (prog.facts && prog.facts.length) {
      var facts = el("div", "facts");
      prog.facts.forEach(function (f) { facts.appendChild(el("span", "cplpw-fact", f)); });
      hero.appendChild(facts);
    }
    frag.appendChild(hero);

    if (liveNote) frag.appendChild(el("div", "cplpw-note", liveNote));

    frag.appendChild(renderTiles(model, prog));
    frag.appendChild(renderMeter(model));

    // Section cards
    var grid = el("div", "cplpw-sections");
    model.sections.forEach(function (s) { grid.appendChild(renderSection(s)); });
    frag.appendChild(grid);

    // Campaign callout
    if (prog.campaign && prog.campaign.headline) {
      var co = el("div", "cplpw-callout");
      co.appendChild(el("div", "k", prog.campaign.kicker || "The outreach message"));
      var headline = prog.campaign.headline
        .replace("{cpl_units}", fmtU(model.cplUnits))
        .replace("{combo_units}", fmtU(model.cplUnits + model.clepUnits));
      co.appendChild(el("div", "h", headline));
      if (prog.campaign.sub) co.appendChild(el("div", "s", prog.campaign.sub));
      frag.appendChild(co);
    }

    // Footnotes
    var foot = el("div", "cplpw-foot");
    (prog.footnotes || []).forEach(function (f) { foot.appendChild(el("div", null, "• " + f)); });
    if (live && live.generatedAt) {
      foot.appendChild(el("div", null, "• CPL ✓ marks derive from the live MAP-platform articulation data in this dashboard’s CER dataset (extracted " + String(live.generatedAt).slice(0, 10) + ")."));
    }
    if (prog.sources && prog.sources.length) {
      var srcRow = el("div", null, "Sources: ");
      prog.sources.forEach(function (s, i) {
        if (i) srcRow.appendChild(document.createTextNode(" · "));
        if (s.url) {
          var a = document.createElement("a");
          a.href = s.url; a.target = "_blank"; a.rel = "noopener";
          a.textContent = s.label || s.url;
          srcRow.appendChild(a);
        } else {
          srcRow.appendChild(document.createTextNode(s.label || ""));
        }
      });
      foot.appendChild(srcRow);
    }
    frag.appendChild(foot);

    clearNode(root);
    root.removeAttribute("style");
    root.appendChild(frag);
  }

  function render(root, data, live, liveNote) {
    var programs = (data && data.programs) || [];
    if (!programs.length) {
      clearNode(root);
      root.appendChild(el("div", "cplpw-empty", "No pathway definitions found (cpl_pathways_data.js)."));
      return;
    }
    var container = el("div", "cplpw");
    var active = 0;
    var body = el("div");
    if (programs.length > 1) {
      var picker = el("div", "cplpw-progrow");
      programs.forEach(function (p, i) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "cplpw-progbtn" + (i === active ? " on" : "");
        b.textContent = (p.college ? p.college + " — " : "") + (p.program || ("Program " + (i + 1)));
        b.addEventListener("click", function () {
          active = i;
          Array.prototype.forEach.call(picker.children, function (c, j) {
            c.className = "cplpw-progbtn" + (j === i ? " on" : "");
          });
          renderProgram(body, programs[i], live, liveNote);
        });
        picker.appendChild(b);
      });
      container.appendChild(picker);
    }
    container.appendChild(body);
    clearNode(root);
    root.removeAttribute("style");
    root.appendChild(container);
    renderProgram(body, programs[active], live, liveNote);
  }

  // ── Boot ──────────────────────────────────────────────────────────────────
  function activate() {
    ensureCss();
    var root = document.getElementById(ROOT_ID);
    if (!root) return;
    if (root.getAttribute("data-cplpw-rendered") === "1") return;
    root.setAttribute("data-cplpw-rendered", "1");

    var data = window.CPL_PATHWAYS || { programs: [] };
    var college = (data.programs && data.programs[0] && data.programs[0].college) || "Cerritos";

    function done(payload, note) {
      var live = null;
      try { live = buildLiveIndexes(payload, college); } catch (e) { live = null; }
      render(root, data, live, live ? null : (note || "Live MAP articulation data unavailable — showing the curated snapshot."));
    }
    // Live CER payload (3 MB, lazy — the CER/MAP-Export tabs share the same file).
    if (window.CPL_CREDENTIAL_REFERENCE) {
      done(window.CPL_CREDENTIAL_REFERENCE);
    } else if (window.CPL_TABS && window.CPL_TABS.loadScript) {
      window.CPL_TABS.loadScript("credential_reference_data.js", "CPL_CREDENTIAL_REFERENCE", function () {
        done(window.CPL_CREDENTIAL_REFERENCE || null);
      });
    } else {
      done(null);
    }
  }

  window.CPL_PATHWAYS_TAB = {
    activate: activate,
    // exposed for tests
    _buildLiveIndexes: buildLiveIndexes,
    _resolvePathway: resolvePathway,
    _courseKey: courseKey,
  };
})();
